mapper.select:
SELECT SO.sale_id ,if(SO.is_old=0, (select shop_name from shop where shop_id = SO.shop_id), (select shop_name from shop where shop_num = SO.shop_id) )shop_name ,(if(SO.is_old=1,(SO.damdang_name),if((SELECT S.staff_name from staff S where S.staff_id = VHC.staff_id) is null,VHC.staff_id,(SELECT S.staff_name from staff S where S.staff_id = VHC.staff_id)))) staff_name ,SO.cstmr_id ,SO.result ,SO.shop_id ,SO.datetime ,SO.result ,SO.ogn_price ,SO.pay_cash ,SO.pay_card ,SO.pay_point ,SO.card_date ,SO.card_ty ,(select card_com_name from card_com_info where card_com_id=SO.card_ty)cname ,SO.partner_dscnt ,SO.partner_id ,SO.dscnt_price ,SO.etc_dscnt ,SO.etc_dscnt_memo ,SO.damdang_name ,SO.gframe1 ,SO.gframe2 ,SO.gframe3 ,SO.glens1 ,SO.glens2 ,SO.glens3 ,SO.clensR ,SO.clensL
,ifnull(SO.is_old,1) as is_old ,SO.ogn_price ,VHC.cstmr_cd ,VHC.staff_id ,VHC.visit_shop_id ,VHC.gsph_right ,VHC.gsph_left ,VHC.gcyl_right ,VHC.gcyl_left ,VHC.gaxis_right ,VHC.gaxis_left ,VHC.add_right ,VHC.add_left ,VHC.npc_right ,VHC.npc_left ,VHC.npa_right ,VHC.npa_left ,VHC.pd_right ,VHC.pd_left ,VHC.lsph_right ,VHC.lsph_left ,VHC.lcyl_right ,VHC.lcyl_left ,VHC.laxis_right ,VHC.laxis_left ,VHC.prism_right ,VHC.prism_left ,VHC.base_right ,VHC.base_left ,VHC.bc_right ,VHC.bc_left ,VHC.dia_right ,VHC.dia_left ,VHC.dom_eye ,(select old_digit from old_digit where id=1) as old_digit FROM sale_off SO
LEFT JOIN visit_history VHC ON SO.cstmr_id=VHC.cstmr_id AND SO.hist_id = VHC.hist_id WHERE SO.cstmr_id=#{cstmrId}
and SO.cancel = 0 and shop_id != 0 ORDER BY SO.datetime desc , SO.hist_id desc;

mapper.update:
UPDATE
	sale_off
SET
	sale_memo = #{saleMemo}
WHERE
	sale_id = #{saleId}
